/**
 * File Resolver
 *
 * Utilities for finding source files and local lib files.
 *
 * @module rendering/orchestrator/file-resolver
 */
import { join } from "../../../platform/compat/path/index.js";
import { rendererLogger as logger } from "../../../utils/index.js";
import { buildCandidatePaths, findFirstExisting } from "./candidates.js";
export { buildCandidatePaths, findFirstExisting } from "./candidates.js";
const SOURCE_EXTENSIONS = [".tsx", ".ts", ".jsx", ".js", ".mdx", ".md"];
const COMPONENT_EXTENSIONS = [".tsx", ".ts", ".jsx", ".js"];
function stripSourceExtension(path) {
    const matched = SOURCE_EXTENSIONS.find((ext) => path.endsWith(ext));
    return matched
        ? { stem: path.slice(0, -matched.length), hasExt: true }
        : { stem: path, hasExt: false };
}
export function getLocalLibDir() {
    const currentFile = new URL(globalThis[Symbol.for("import-meta-ponyfill-esmodule")](import.meta).url).pathname;
    const srcIndex = currentFile.indexOf("/src/");
    if (srcIndex !== -1)
        return `${currentFile.substring(0, srcIndex)}/src/lib`;
    return currentFile.replace(/\/src\/rendering\/orchestrator\/file-resolver\/index\.ts$/, "/src/lib");
}
export async function findLocalLibFile(relativePath, localAdapter) {
    const libDir = getLocalLibDir();
    const fileName = relativePath.replace(/^lib\//, "");
    const candidates = buildCandidatePaths(libDir, fileName, COMPONENT_EXTENSIONS);
    const result = await findFirstExisting(candidates, (p) => localAdapter.fs.stat(p));
    logger.debug(result ? "[FileResolver] Found local lib file:" : "[FileResolver] Local lib file not found:", result ?? relativePath);
    return result;
}
export async function findSourceFile(basePath, projectDir, adapter, options = {}) {
    // When the specifier already carries an explicit source extension
    // (e.g. `@/components/Welcome.tsx`), the literal on-disk path must be a
    // candidate. `buildCandidatePaths` only produces `${fileName}${ext}` and
    // `${fileName}/index${ext}` variants, so without stripping the extension
    // here the file would never match.
    const { stem, hasExt: hasExplicitExt } = stripSourceExtension(basePath);
    if (adapter.fs.resolveFile) {
        const directBases = [];
        if (hasExplicitExt)
            directBases.push(join(projectDir, basePath));
        directBases.push(join(projectDir, stem));
        const legacyBases = [];
        const stemWithoutComponents = stem.replace(/^components\//, "");
        if (stemWithoutComponents !== stem) {
            if (hasExplicitExt) {
                legacyBases.push(join(projectDir, basePath.replace(/^components\//, "")));
            }
            legacyBases.push(join(projectDir, stemWithoutComponents));
            directBases.push(...legacyBases);
        }
        for (const candidateBase of directBases) {
            const resolved = await adapter.fs.resolveFile(candidateBase, {
                allowPagesPrefix: false,
            });
            if (resolved) {
                if (legacyBases.includes(candidateBase))
                    options.onLegacyComponentsFallback?.();
                logger.debug("[FileResolver] Found file via resolveFile:", resolved);
                return resolved;
            }
        }
    }
    const candidates = [];
    if (hasExplicitExt)
        candidates.push(join(projectDir, basePath));
    candidates.push(...buildCandidatePaths(projectDir, stem, SOURCE_EXTENSIONS));
    const legacyCandidates = [];
    const stemWithoutComponents = stem.replace(/^components\//, "");
    if (stemWithoutComponents !== stem) {
        if (hasExplicitExt) {
            legacyCandidates.push(join(projectDir, basePath.replace(/^components\//, "")));
        }
        legacyCandidates.push(...buildCandidatePaths(projectDir, stemWithoutComponents, SOURCE_EXTENSIONS));
        candidates.push(...legacyCandidates);
    }
    const result = await findFirstExisting(candidates, (p) => adapter.fs.stat(p));
    if (result && legacyCandidates.includes(result))
        options.onLegacyComponentsFallback?.();
    logger.debug(result ? "[FileResolver] Found file:" : "[FileResolver] File not found:", result ?? basePath);
    return result;
}
